-- REVIEW ONLY: exact transaction generated by the self-contained command in
-- docs/customer-history-exact-repair.md. Do not execute standalone.
-- No production mutation is authorized. The command first requires all-host
-- writer quiescence, fresh project-wide active-job checks, restricted backups,
-- exact backup multiset verification and a separately provisioned guard.
-- PROJECT and backup references below are review placeholders; the command
-- derives the actual project from existing config and creates unique backups.
-- @checked_at is a TIMESTAMP bound only after its fresh checks succeed.
BEGIN TRANSACTION;
ASSERT TIMESTAMP_DIFF(CURRENT_TIMESTAMP(),@checked_at,SECOND) BETWEEN 0 AND 15 AS 'Job and publisher checks stale';
ASSERT (SELECT COUNT(*) FROM `PROJECT.customer_identity.identity_publication_guard`)=1 AND (SELECT COUNTIF(guard_id='publication' AND generation IS NOT NULL AND generation>=0) FROM `PROJECT.customer_identity.identity_publication_guard`)=1 AS 'Publication guard unavailable';
UPDATE `PROJECT.customer_identity.identity_publication_guard` SET generation=generation+1 WHERE guard_id='publication' AND generation IS NOT NULL;
ASSERT @@row_count=1 AS 'Publication guard unavailable';
CREATE TEMP TABLE repair_markers AS SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at FROM `PROJECT.customer_identity.identity_snapshots` WHERE snapshot_id='history-20261022-billing-v3';
CREATE TEMP TABLE repair_original_links AS SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email FROM `PROJECT.customer_identity.identity_order_links` WHERE snapshot_id='history-20261022-billing-v3';
CREATE TEMP TABLE repair_links AS SELECT DISTINCT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email FROM repair_original_links;
CREATE TEMP TABLE repair_keys AS SELECT source_store,source_order_id,COUNT(*) copies FROM repair_original_links GROUP BY source_store,source_order_id;
ASSERT (SELECT COUNT(*) FROM repair_markers)=2 AS 'Expected exactly two markers';
ASSERT (SELECT COUNT(*) FROM (SELECT DISTINCT state,start_date,end_date,mapping_count FROM repair_markers))=1 AS 'Marker metadata conflict';
ASSERT (SELECT COUNT(*) FROM repair_markers WHERE state='ready' AND start_date=DATE '1900-01-01' AND end_date=DATE '2026-10-19' AND mapping_count=58465)=2 AS 'Intended metadata changed';
ASSERT (SELECT COUNT(*) FROM repair_markers WHERE created_at=TIMESTAMP '2026-10-22T07:31:49.447Z')=1 AND (SELECT COUNT(*) FROM repair_markers WHERE created_at=TIMESTAMP '2026-10-22T07:32:17.761Z')=1 AS 'Marker timestamps changed';
ASSERT (SELECT COUNT(*) FROM repair_original_links)=116930 AS 'Original row count changed';
ASSERT (SELECT COUNT(*) FROM repair_keys WHERE copies>1)=58465 AND NOT EXISTS(SELECT 1 FROM repair_keys WHERE copies!=2) AS 'Duplicate key multiplicity changed';
ASSERT NOT EXISTS(SELECT 1 FROM repair_links WHERE source_store IS NULL OR source_store NOT IN ('ww','usd','shopify') OR source_order_id IS NULL OR source_order_id='' OR canonical_customer_ref IS NULL OR NOT REGEXP_CONTAINS(canonical_customer_ref,r'^c_[A-Fa-f0-9]{64}$') OR resolution IS NULL OR resolution NOT IN ('matched','unmatched','ambiguous','unavailable')) AS 'Invalid mapping';
ASSERT NOT EXISTS(SELECT 1 FROM repair_links GROUP BY source_store,source_order_id HAVING COUNT(*)>1) AS 'Conflicting complete mapping';
ASSERT (SELECT COUNT(*) FROM repair_links)=58465 AND (SELECT COUNT(*) FROM repair_keys)=58465 AS 'Distinct mapping count changed';
ASSERT (SELECT COUNT(*) FROM repair_links WHERE source_store='ww')=39176 AND (SELECT COUNT(*) FROM repair_links WHERE source_store='usd')=4322 AND (SELECT COUNT(*) FROM repair_links WHERE source_store='shopify')=14967 AS 'Distinct source totals changed';
ASSERT (SELECT COUNT(*) FROM (SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email,COUNT(*) copies FROM repair_original_links GROUP BY snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email HAVING COUNT(*)=2))=58465 AS 'Mappings are not identical pairs';
ASSERT NOT EXISTS(SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at,COUNT(*) copies FROM repair_markers GROUP BY snapshot_id,state,start_date,end_date,mapping_count,created_at EXCEPT DISTINCT SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at,COUNT(*) copies FROM `PROJECT.RESTRICTED_BACKUP_DATASET.REVIEWED_MARKER_BACKUP` GROUP BY snapshot_id,state,start_date,end_date,mapping_count,created_at) AS 'Marker backup missing';
ASSERT NOT EXISTS(SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at,COUNT(*) copies FROM `PROJECT.RESTRICTED_BACKUP_DATASET.REVIEWED_MARKER_BACKUP` GROUP BY snapshot_id,state,start_date,end_date,mapping_count,created_at EXCEPT DISTINCT SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at,COUNT(*) copies FROM repair_markers GROUP BY snapshot_id,state,start_date,end_date,mapping_count,created_at) AS 'Marker backup added';
ASSERT NOT EXISTS(SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email,COUNT(*) copies FROM repair_original_links GROUP BY snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email EXCEPT DISTINCT SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email,COUNT(*) copies FROM `PROJECT.RESTRICTED_BACKUP_DATASET.REVIEWED_LINK_BACKUP` GROUP BY snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email) AS 'Link backup missing';
ASSERT NOT EXISTS(SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email,COUNT(*) copies FROM `PROJECT.RESTRICTED_BACKUP_DATASET.REVIEWED_LINK_BACKUP` GROUP BY snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email EXCEPT DISTINCT SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email,COUNT(*) copies FROM repair_original_links GROUP BY snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email) AS 'Link backup added';
CREATE TEMP TABLE retained_marker AS SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at FROM repair_markers WHERE created_at=TIMESTAMP '2026-10-22T07:31:49.447Z';
DELETE FROM `PROJECT.customer_identity.identity_order_links` WHERE snapshot_id='history-20261022-billing-v3';
INSERT INTO `PROJECT.customer_identity.identity_order_links` (snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email) SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email FROM repair_links;
DELETE FROM `PROJECT.customer_identity.identity_snapshots` WHERE snapshot_id='history-20261022-billing-v3';
INSERT INTO `PROJECT.customer_identity.identity_snapshots` (snapshot_id,state,start_date,end_date,mapping_count,created_at) SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at FROM retained_marker;
ASSERT (SELECT COUNT(*) FROM `PROJECT.customer_identity.identity_order_links` WHERE snapshot_id='history-20261022-billing-v3')=58465 AS 'Link postcondition';
ASSERT (SELECT COUNT(*) FROM `PROJECT.customer_identity.identity_snapshots` WHERE snapshot_id='history-20261022-billing-v3')=1 AS 'Marker postcondition';
ASSERT NOT EXISTS(SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email FROM repair_links EXCEPT DISTINCT SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email FROM `PROJECT.customer_identity.identity_order_links` WHERE snapshot_id='history-20261022-billing-v3') AS 'Exact mapping set missing';
ASSERT NOT EXISTS(SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email FROM `PROJECT.customer_identity.identity_order_links` WHERE snapshot_id='history-20261022-billing-v3' EXCEPT DISTINCT SELECT snapshot_id,source_store,source_order_id,source_customer_id,canonical_customer_ref,resolution,financial_status,cancelled,conflicting_email,shared_email FROM repair_links) AS 'Exact mapping set added';
ASSERT NOT EXISTS(SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at FROM retained_marker EXCEPT DISTINCT SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at FROM `PROJECT.customer_identity.identity_snapshots` WHERE snapshot_id='history-20261022-billing-v3') AS 'Original marker missing';
ASSERT NOT EXISTS(SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at FROM `PROJECT.customer_identity.identity_snapshots` WHERE snapshot_id='history-20261022-billing-v3' EXCEPT DISTINCT SELECT snapshot_id,state,start_date,end_date,mapping_count,created_at FROM retained_marker) AS 'Original marker added';
COMMIT TRANSACTION;
